function usageStatus() {
  if (gemini.ok && ai) return 'success'
  const code = gemini.ok ? 'invalid_response' : gemini.code
  if (code === 'invalid_response' || code === 'blocked') return 'invalid_response'
  if (code === 'timeout') return 'timeout'
  return 'error'
}
