const usagePatch = reservationId
  ? {
      status: usageStatus(),
      latency_ms: Math.max(0, aiCheckedAt - (req.marks.aiRequestBuiltAt ?? aiCheckedAt)),
      prompt_tokens: tokens ? tokens.promptTokens : null,
      output_tokens: tokens ? tokens.outputTokens : null,
