    }
  : null

const lead = ctx.lead
const leadInsert = {
  workspace_id: ctx.config.workspaceId,
  name: lead.name,
  email: lead.email,
  phone: lead.phone,
  company: lead.company,
  job_title: lead.jobTitle,
